# Use backtracking search
def solve_all_interval():
    N = 14
    x = [None] * N
    used_x = set()
    used_d = set()

    # Fixed assignments
    x[6] = 3
    x[12] = 6
    used_x.add(3)
    used_x.add(6)

    # d[3] = 10, d[11] = 2
    fixed_d = {3: 10, 11: 2}

    def backtrack(pos):
        if pos == N:
            return True

        if x[pos] is not None:
            # Position is fixed, check constraints with previous
            if pos > 0 and x[pos-1] is not None:
                diff = abs(x[pos] - x[pos-1])
                d_idx = pos - 1
                if d_idx in fixed_d:
                    if diff != fixed_d[d_idx]:
                        return False
                if diff == 0 or diff > 13:
                    return False
                if diff in used_d:
                    return False
                used_d.add(diff)
                result = backtrack(pos + 1)
                used_d.remove(diff)
                return result
            else:
                return backtrack(pos + 1)

        for val in range(N):
            if val in used_x:
                continue

            # Check difference constraint with previous position
            if pos > 0 and x[pos-1] is not None:
                diff = abs(val - x[pos-1])
                d_idx = pos - 1
                if d_idx in fixed_d and diff != fixed_d[d_idx]:
                    continue
                if diff == 0 or diff > 13:
                    continue
                if diff in used_d:
                    continue

                x[pos] = val
                used_x.add(val)
                used_d.add(diff)

                if backtrack(pos + 1):
                    return True

                x[pos] = None
                used_x.remove(val)
                used_d.remove(diff)
            else:
                x[pos] = val
                used_x.add(val)

                if backtrack(pos + 1):
                    return True

                x[pos] = None
                used_x.remove(val)

        return False

    if backtrack(0):
        return x
    return None

result = solve_all_interval()
if result:
    print("Solution:", result)
    d_vals = [abs(result[i+1] - result[i]) for i in range(13)]
    print("Differences:", d_vals)
    print("x permutation check:", sorted(result) == list(range(14)))
    print("d permutation check:", sorted(d_vals) == list(range(1, 14)))
    print("x[6]=3:", result[6] == 3)
    print("x[12]=6:", result[12] == 6)
    print("d[3]=10:", d_vals[3] == 10)
    print("d[11]=2:", d_vals[11] == 2)
else:
    print("No solution found")
